"""Offline printable HTML. All user text is escaped before rendering."""
from html import escape

COLUMNS=['Details','Unit','Opening','Receivings','Total stock','Closing','Drawings','Broken','Sold','Unit price','Total amount']


def table(headers,rows):
    def cell(value):return escape(str(value))
    return '<table><thead><tr>'+''.join('<th>'+cell(v)+'</th>' for v in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+cell(v)+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table>'


def printable(ledger,period):
    rows,totals=ledger.report(period)
    dates=ledger.db.execute('SELECT start,end FROM periods WHERE id=?',(period,)).fetchone()
    if not dates:raise ValueError('Reporting period not found.')
    warnings=ledger.checks(period)
    balances=[[r['name'],f"{r['credit']/100:.2f}",f"{r['paid']/100:.2f}",f"{(r['credit']-r['paid'])/100:.2f}"] for r in ledger.customer_balances()]
    return '''<!doctype html><html><head><meta charset="utf-8"><title>Family Shop — stock and income report</title>
<style>body{font:14px Arial,sans-serif;color:#172b35;max-width:1300px;margin:30px auto;padding:0 18px}h1{color:#17685b}h2{margin-top:30px}table{border-collapse:collapse;width:100%;margin:15px 0}th,td{border:1px solid #cbd5da;padding:8px;text-align:right}th{background:#eaf4f0}td:first-child,th:first-child{text-align:left}.note{padding:12px;background:#fff4da}.sign{margin-top:40px;line-height:3}button{padding:10px 20px;cursor:pointer}@media print{button{display:none}body{font-size:10px;margin:0;max-width:none}th,td{padding:5px}thead{display:table-header-group}tr{break-inside:avoid}.sign{break-inside:avoid}@page{size:A4 landscape;margin:12mm}}</style></head><body>
<button onclick="window.print()">Print / Save as PDF</button><h1>FAMILY SHOP</h1>''' + f'<p>Stock and income report | {escape(dates[0])} to {escape(dates[1])} | USD</p>' + '<p class="note">Provisional report based on complete stock counts and supplied costs. Stock-implied sales may include unexplained losses; investigate the reconciliation difference. Customer balances below cover all recorded dates, not only this period.</p>'+ ('<h2>Checks requiring attention</h2><ul>'+''.join('<li>'+escape(w)+'</li>' for w in warnings)+'</ul>' if warnings else '')+'<h2>Stock sheet</h2>'+table(COLUMNS,rows)+'<h2>Reconciliation and income statement</h2>'+table(['Details','Amount USD'],totals.items())+'<p>Cost of goods sold uses periodic weighted-average cost, including allocated delivery costs. Total-sales entries retain the entered amount and show an average selling price. Drawings are excluded from sales and expenses. Unexplained cash differences are not automatically deducted from profit.</p><h2>Customer balances — all recorded dates</h2>'+table(['Customer','Credit sales USD','Repaid USD','Balance USD'],balances)+'<div class="sign">Prepared by: __________________________ &nbsp; Signature: __________________________<br>Checked by: __________________________ &nbsp; Signature: __________________________<br>Date: __________________________</div></body></html>'


BRAND_PAYLOAD = ''

APP_ID = 'FamilyShop.Desktop.App'


def materialize_brand():
    import base64,json,zlib
    payload=json.loads(zlib.decompress(base64.b64decode(BRAND_PAYLOAD)))
    folder=DATA/'assets';folder.mkdir(exist_ok=True)
    for ext in ('ico','png'):
        path=folder/('family-shop-v1.'+ext);data=base64.b64decode(payload[ext])
        if not path.exists() or path.read_bytes()!=data:path.write_bytes(data)
    return folder


def set_process_identity():
    if os.name=='nt':
        try:
            import ctypes
            function=ctypes.windll.shell32.SetCurrentProcessExplicitAppUserModelID
            function.argtypes=[ctypes.c_wchar_p];function.restype=ctypes.c_long
            function(APP_ID)
        except (AttributeError,OSError):pass


def set_shortcut_identity(path):
    """Match the shortcut AppUserModelID to the running app (Windows COM)."""
    if os.name!='nt':return
    import ctypes as C
    from ctypes import wintypes as W
    import uuid
    class GUID(C.Structure):
        _fields_=[('data',C.c_ubyte*16)]
        def __init__(self,text):super().__init__((C.c_ubyte*16).from_buffer_copy(uuid.UUID(text).bytes_le))
    class PROPERTYKEY(C.Structure):_fields_=[('fmtid',GUID),('pid',W.DWORD)]
    class VALUE(C.Union):_fields_=[('text',C.c_wchar_p),('padding',C.c_ubyte*16)]
    class PROPVARIANT(C.Structure):_fields_=[('vt',W.WORD),('a',W.WORD),('b',W.WORD),('c',W.WORD),('value',VALUE)]
    ole=C.OleDLL('ole32');ole.CoInitialize(None)
    link=C.c_void_p();persist=C.c_void_p();store=C.c_void_p()
    def call(ptr,index,types,*args):
        table=C.cast(ptr,C.POINTER(C.POINTER(C.c_void_p))).contents
        return C.WINFUNCTYPE(C.c_long,C.c_void_p,*types)(table[index])(ptr,*args)
    def checked(result):
        if result<0:raise OSError('Windows shortcut identity could not be updated.')
    try:
        cls=GUID('00021401-0000-0000-C000-000000000046');iid=GUID('000214F9-0000-0000-C000-000000000046')
        ole.CoCreateInstance.argtypes=[C.POINTER(GUID),C.c_void_p,W.DWORD,C.POINTER(GUID),C.POINTER(C.c_void_p)]
        checked(ole.CoCreateInstance(C.byref(cls),None,1,C.byref(iid),C.byref(link)))
        iidfile=GUID('0000010B-0000-0000-C000-000000000046')
        checked(call(link,0,[C.POINTER(GUID),C.POINTER(C.c_void_p)],C.byref(iidfile),C.byref(persist)))
        checked(call(persist,5,[C.c_wchar_p,W.DWORD],str(path),2))
        iidstore=GUID('886D8EEB-8CF2-4446-8D02-CDBA1DBDCF99')
        checked(call(link,0,[C.POINTER(GUID),C.POINTER(C.c_void_p)],C.byref(iidstore),C.byref(store)))
        key=PROPERTYKEY(GUID('9F4C2855-9F79-4B39-A8D0-E1D42DE1D5F3'),5)
        value=PROPVARIANT();value.vt=31;value.value.text=APP_ID
        checked(call(store,6,[C.POINTER(PROPERTYKEY),C.POINTER(PROPVARIANT)],C.byref(key),C.byref(value)))
        checked(call(store,7,[]))
        checked(call(persist,6,[C.c_wchar_p,W.BOOL],str(path),True))
    finally:
        for pointer in (store,persist,link):
            if pointer:call(pointer,2,[])
        ole.CoUninitialize()


def scroll_target(widget,axis,motion,parents):
    """Route to the nearest viewport that can move, then its enclosing page."""
    seen=set()
    while widget is not None:
        target=parents.get(widget,widget)
        if target not in seen:
            seen.add(target)
            view=getattr(target,axis+'view',None)
            if view:
                try:
                    first,last=map(float,view())
                    if (motion<0 and first>0.000001) or (motion>0 and last<0.999999):return target
                except (tk.TclError,TypeError,ValueError):pass
        widget=getattr(widget,'master',None)
    return None


