    def draw_symbol(self,canvas,index):
        canvas.create_oval(1,1,41,41,fill=['#e5f7ef','#fff2dc','#eaf0ff','#e4f4f5'][index],outline='')
        color=['#218468','#b17a29','#617ac6','#357c86'][index]
        if index==0:
            canvas.create_rectangle(12,13,30,30,outline=color,width=2);canvas.create_line(12,18,30,18,fill=color,width=2);canvas.create_line(21,13,21,30,fill=color,width=2)
        elif index==1:
            canvas.create_rectangle(9,15,25,27,outline=color,width=2);canvas.create_rectangle(25,20,32,27,outline=color,width=2)
            for x in (14,28):canvas.create_oval(x-3,25,x+3,31,fill=color,outline='')
        elif index==2:
            for y in (13,21,29):
                canvas.create_line(12,y,15,y+3,19,y-3,fill=color,width=2);canvas.create_line(24,y,31,y,fill=color,width=2)
        else:
            canvas.create_rectangle(10,14,32,29,outline=color,width=2);canvas.create_oval(18,18,24,25,outline=color,width=2)

    def desktop_shortcut(self,existing_only=False):
        if os.name!='nt':return
        try:
            script=Path(__file__).resolve().parent/'setup_shortcut.vbs'
            args=['cscript.exe','//NoLogo',str(script),sys.executable,'quiet']
            if existing_only:args.append('existing')
            result=subprocess.run(args,capture_output=True,text=True,timeout=20,creationflags=getattr(subprocess,'CREATE_NO_WINDOW',0))
            if result.returncode:raise OSError('Windows could not update the shortcut.')
            target=result.stdout.strip()
            if target and Path(target).exists():
                try:set_shortcut_identity(Path(target))
                except (OSError,AttributeError):pass
            if not existing_only:messagebox.showinfo('Desktop shortcut ready','Family Shop now has its own desktop icon. Close and reopen from that shortcut. If an old Python shortcut is pinned, unpin it and pin the new Family Shop shortcut.')
        except Exception as exc:
            if not existing_only:messagebox.showerror('Shortcut could not be updated',str(exc))

    def apply_theme(self):
        self.configure(bg='#f2f6f6')
